def compute(vars):
    old_balance = vars["v1"]
    new_balance = vars["v2"]

    if old_balance == 0:
        return None

    change = new_balance - old_balance
    value = (change / old_balance) * 100

    return {
        "value": value,
        "trace": {
            "old_balance": old_balance,
            "new_balance": new_balance,
            "change": change,
            "output_meta": {
                "currency": "USD",
                "scale": "million",
                "unit": "percentage"
            }
        }
    }
